messages.say:
I’m building this as a single-file editorial viewer you can drop into your portfolio or load in an iframe, with spread layouts, page-turn motion, thumbnails, and room for your campaign images and microtext.


Thought for 21s


Ranaan-ccc-editorial-template


<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>RANAAN × CCC — Editorial Viewer</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Playfair+Display:ital,wght@0,600;0,800;1,400;1,600&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #080808;
      --panel: #0d0d0d;
      --panel-2: #121212;
      --paper: #f0ebe2;
      --paper-2: #e7dfd1;
      --ink: #101010;
      --muted: #8e857b;
      --line: rgba(255,255,255,0.08);
      --white: #ffffff;
      --bone: #f0ebe2;
      --ash: #555555;
      --blood: #1a0a0a;
      --accent: #4b1f2a;
      --gold: #c5ad70;
      --shadow: 0 30px 80px rgba(0,0,0,0.5);
      --shadow-soft: 0 18px 40px rgba(0,0,0,0.28);
      --radius: 22px;
      --page-ratio: 1.414;
      --viewer-max: 1440px;
      --dur: 620ms;
      --ease: cubic-bezier(.2,.82,.2,1);
    }

    * { box-sizing: border-box; }
    html, body { height: 100%; }
    body {
      margin: 0;
      background:
        radial-gradient(circle at top, rgba(255,255,255,0.05), transparent 26%),
        linear-gradient(180deg, #121212 0%, #090909 55%, #060606 100%);
      color: var(--white);
      font-family: "Space Mono", monospace;
      overflow: hidden;
    }

    body::before {
      content: "";
      position: fixed;
      inset: 0;
      pointer-events: none;
      opacity: 0.2;
      background-image:
        linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
      background-size: 24px 24px;
      mask-image: radial-gradient(circle at center, black 45%, transparent 85%);
    }

    .viewer-shell {
      height: 100%;
      display: grid;
      grid-template-columns: 86px minmax(0,1fr) 86px;
      grid-template-rows: 72px minmax(0,1fr) 96px;
      gap: 0;
    }

    .topbar {
      grid-column: 1 / -1;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 18px 26px;
      border-bottom: 1px solid var(--line);
      background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));
      backdrop-filter: blur(14px);
      z-index: 20;
    }

    .brand {
      display: flex;
      flex-direction: column;
      gap: 2px;
      min-width: 0;
    }
    .brand small,
    .meta,
    .spread-count,
    .thumb-label,
    .page-foot,
    .caption,
    .micro,
    .notes,
    .nav-btn span,
    .toggle,
    .chip {
      font-size: 10px;
      letter-spacing: 0.22em;
      text-transform: uppercase;
    }
    .brand small { color: var(--muted); }
    .brand strong {
      font-family: "Bebas Neue", sans-serif;
      font-size: 30px;
      letter-spacing: 0.06em;
      line-height: 0.92;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .topbar-actions {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .chip,
    .toggle,
    .icon-btn,
    .nav-btn {
      appearance: none;
      border: 1px solid rgba(255,255,255,0.08);
      color: var(--white);
      background: rgba(255,255,255,0.03);
      border-radius: 999px;
      cursor: pointer;
      transition: transform 180ms ease, background 180ms ease, border-color 180ms ease, opacity 180ms ease;
    }
    .chip,
    .toggle,
    .icon-btn {
      height: 36px;
      padding: 0 14px;
    }
    .chip:hover,
    .toggle:hover,
    .icon-btn:hover,
    .nav-btn:hover {
      transform: translateY(-1px);
      background: rgba(255,255,255,0.08);
      border-color: rgba(255,255,255,0.12);
    }

    .side-rail {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 12px;
      z-index: 5;
    }

    .nav-btn {
      width: 54px;
      height: 54px;
      border-radius: 50%;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      background: rgba(255,255,255,0.04);
      box-shadow: var(--shadow-soft);
    }
    .nav-btn[disabled] {
      opacity: 0.35;
      cursor: not-allowed;
      transform: none;
    }
    .nav-btn svg {
      width: 18px;
      height: 18px;
    }

    .stage-wrap {
      position: relative;
      display: grid;
      place-items: center;
      padding: 22px clamp(12px, 2vw, 22px) 12px;
      overflow: hidden;
      perspective: 2200px;
      min-width: 0;
      min-height: 0;
    }

    .stage-wrap::before {
      content: "";
      position: absolute;
      width: min(78vw, 1080px);
      height: min(70vh, 760px);
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255,255,255,0.07) 0%, transparent 70%);
      filter: blur(20px);
      pointer-events: none;
      transform: translateY(4%);
    }

    .magazine {
      position: relative;
      width: min(100%, var(--viewer-max));
      height: min(100%, calc((100vw - 280px) * 0.58));
      max-height: 76vh;
      min-height: 420px;
      min-width: 0;
    }

    .spread-stack {
      position: relative;
      width: 100%;
      height: 100%;
      transform-style: preserve-3d;
    }

    .spread {
      position: absolute;
      inset: 0;
      display: grid;
      grid-template-columns: 1fr 1fr;
      background: linear-gradient(180deg, #ede5d8, #e7dfd1);
      color: var(--ink);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow);
      transform-origin: center center;
      opacity: 0;
      pointer-events: none;
      transform: translateX(60px) rotateY(-10deg) scale(0.985);
      transition:
        transform var(--dur) var(--ease),
        opacity 340ms ease;
    }

    .spread.active {
      opacity: 1;
      pointer-events: auto;
      transform: translateX(0) rotateY(0deg) scale(1);
      z-index: 4;
    }
    .spread.before {
      opacity: 0;
      transform: translateX(-70px) rotateY(14deg) scale(0.98);
      z-index: 2;
    }
    .spread.after {
      opacity: 0;
      transform: translateX(70px) rotateY(-14deg) scale(0.98);
      z-index: 2;
    }

    .spread.turn-next {
      animation: turnNext var(--dur) var(--ease) both;
      z-index: 6;
    }
    .spread.turn-prev {
      animation: turnPrev var(--dur) var(--ease) both;
      z-index: 6;
    }

    @keyframes turnNext {
      0% { transform: translateX(0) rotateY(0deg) scale(1); opacity: 1; }
      35% { transform: translateX(-2%) rotateY(12deg) scale(0.995); opacity: 1; }
      100% { transform: translateX(-18%) rotateY(28deg) scale(0.985); opacity: 0; }
    }
    @keyframes turnPrev {
      0% { transform: translateX(0) rotateY(0deg) scale(1); opacity: 1; }
      35% { transform: translateX(2%) rotateY(-12deg) scale(0.995); opacity: 1; }
      100% { transform: translateX(18%) rotateY(-28deg) scale(0.985); opacity: 0; }
    }

    .spread::before,
    .spread::after {
      content: "";
      position: absolute;
      top: 0;
      bottom: 0;
      width: 22px;
      pointer-events: none;
      z-index: 3;
    }
    .spread::before {
      left: calc(50% - 11px);
      background: linear-gradient(90deg, rgba(0,0,0,0.15), rgba(255,255,255,0.08), rgba(0,0,0,0.15));
      opacity: 0.65;
    }
    .spread::after {
      right: 0;
      background: linear-gradient(90deg, transparent, rgba(0,0,0,0.08));
      opacity: 0.45;
    }

    .page {
      position: relative;
      min-width: 0;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 28px;
      background:
        radial-gradient(circle at top left, rgba(255,255,255,0.35), transparent 35%),
        linear-gradient(180deg, rgba(255,255,255,0.18), rgba(0,0,0,0.03));
    }

    .page.dark {
      background:
        radial-gradient(circle at top left, rgba(255,255,255,0.06), transparent 30%),
        linear-gradient(180deg, #0d0d0d, #141414);
      color: var(--bone);
    }

    .page::after {
      content: "";
      position: absolute;
      inset: 0;
      opacity: 0.12;
      background-image:
        linear-gradient(rgba(0,0,0,0.18) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0,0,0,0.12) 1px, transparent 1px);
      background-size: 24px 24px;
      pointer-events: none;
      mix-blend-mode: multiply;
    }

    .page.dark::after {
      background-image:
        linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
      mix-blend-mode: screen;
    }

    .page-head,
    .page-foot {
      position: relative;
      z-index: 1;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }

    .page-no {
      font-size: 10px;
      letter-spacing: 0.28em;
      opacity: 0.7;
    }

    .kicker {
      font-size: 10px;
      letter-spacing: 0.26em;
      text-transform: uppercase;
      color: var(--muted);
    }

    .page.dark .kicker,
    .page.dark .page-no,
    .page.dark .micro,
    .page.dark .notes,
    .page.dark .caption {
      color: rgba(240,235,226,0.7);
    }

    .hero-title,
    .spread-title,
    .side-title {
      font-family: "Bebas Neue", sans-serif;
      letter-spacing: 0.04em;
      line-height: 0.92;
      text-transform: uppercase;
      margin: 0;
      position: relative;
      z-index: 1;
    }
    .hero-title { font-size: clamp(54px, 6vw, 110px); }
    .spread-title { font-size: clamp(34px, 3.2vw, 68px); }
    .side-title { font-size: clamp(20px, 1.8vw, 34px); }

    .deck-line {
      margin: 14px 0 0;
      font-family: "Playfair Display", serif;
      font-style: italic;
      font-size: clamp(14px, 1.15vw, 18px);
      color: rgba(16,16,16,0.68);
      position: relative;
      z-index: 1;
      max-width: 32ch;
    }
    .page.dark .deck-line { color: rgba(240,235,226,0.7); }

    .cover-block {
      display: flex;
      flex-direction: column;
      gap: 14px;
      justify-content: center;
      height: 100%;
      position: relative;
      z-index: 1;
    }

    .logo-outline {
      font-family: "Playfair Display", serif;
      font-size: clamp(24px, 2vw, 36px);
      line-height: 1;
      color: transparent;
      -webkit-text-stroke: 1px rgba(255,255,255,0.45);
      margin-top: 2px;
    }

    .img-panel,
    .thumb-media {
      position: relative;
      overflow: hidden;
      border-radius: 18px;
      background:
        linear-gradient(135deg, rgba(0,0,0,0.18), rgba(255,255,255,0.12)),
        var(--panel);
    }

    .img-panel {
      height: 100%;
      min-height: 260px;
      display: flex;
      align-items: stretch;
      justify-content: stretch;
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.07);
    }

    .img-panel img,
    .thumb-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      filter: saturate(0.9) contrast(1.02);
    }

    .img-panel.placeholder,
    .thumb-media.placeholder {
      background:
        radial-gradient(circle at top right, rgba(255,255,255,0.12), transparent 25%),
        linear-gradient(135deg, #191919, #0e0e0e 55%, #1a0a0a);
    }

    .img-panel.placeholder::before,
    .thumb-media.placeholder::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(rgba(255,255,255,0.04) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.04) 1px, transparent 1px);
      background-size: 28px 28px;
      opacity: 0.45;
    }

    .img-panel.placeholder::after,
    .thumb-media.placeholder::after {
      content: attr(data-label);
      position: absolute;
      left: 22px;
      bottom: 18px;
      font-size: 10px;
      letter-spacing: 0.24em;
      text-transform: uppercase;
      color: rgba(240,235,226,0.72);
      z-index: 1;
    }

    .micrographics {
      position: absolute;
      inset: 0;
      pointer-events: none;
      z-index: 2;
    }

    .micrographics::before,
    .micrographics::after {
      content: "";
      position: absolute;
      border: 1px solid rgba(255,255,255,0.15);
      width: 18px;
      height: 18px;
    }

    .micrographics::before { top: 14px; left: 14px; border-right: 0; border-bottom: 0; }
    .micrographics::after { right: 14px; bottom: 14px; border-left: 0; border-top: 0; }

    .micro-tag {
      position: absolute;
      font-size: 9px;
      letter-spacing: 0.22em;
      text-transform: uppercase;
      color: rgba(255,255,255,0.62);
      background: rgba(0,0,0,0.28);
      padding: 6px 8px;
      border-radius: 999px;
      border: 1px solid rgba(255,255,255,0.08);
      backdrop-filter: blur(6px);
    }

    .pull-quote {
      font-family: "Playfair Display", serif;
      font-style: italic;
      font-size: clamp(20px, 1.9vw, 30px);
      line-height: 1.2;
      max-width: 12ch;
      margin: 20px 0 0;
      position: relative;
      z-index: 1;
    }

    .body-copy,
    .notes,
    .micro-list,
    .caption {
      position: relative;
      z-index: 1;
    }

    .body-copy {
      font-size: 13px;
      line-height: 1.85;
      max-width: 48ch;
      color: rgba(16,16,16,0.82);
    }
    .page.dark .body-copy { color: rgba(240,235,226,0.78); }

    .micro-list {
      display: grid;
      gap: 10px;
      margin-top: 18px;
    }
    .micro {
      display: flex;
      justify-content: space-between;
      gap: 18px;
      border-top: 1px solid rgba(0,0,0,0.08);
      padding-top: 10px;
      color: rgba(16,16,16,0.72);
    }
    .page.dark .micro { border-top-color: rgba(255,255,255,0.08); }

    .notes {
      display: grid;
      gap: 6px;
      margin-top: 16px;
      color: rgba(16,16,16,0.62);
    }

    .caption {
      display: flex;
      align-items: center;
      gap: 10px;
      color: rgba(16,16,16,0.72);
    }
    .caption::before {
      content: "";
      width: 22px;
      height: 1px;
      background: currentColor;
      opacity: 0.5;
    }

    .thumb-dock {
      grid-column: 1 / -1;
      display: grid;
      grid-template-columns: 180px minmax(0,1fr) 150px;
      gap: 14px;
      align-items: center;
      padding: 12px 20px 18px;
      border-top: 1px solid var(--line);
      background: linear-gradient(180deg, rgba(255,255,255,0.01), rgba(255,255,255,0.03));
    }

    .thumb-dock .left-meta,
    .thumb-dock .right-meta {
      min-width: 0;
      color: var(--muted);
    }

    .thumb-strip {
      display: flex;
      gap: 12px;
      overflow-x: auto;
      padding-bottom: 4px;
      scrollbar-width: thin;
      scrollbar-color: rgba(255,255,255,0.18) transparent;
    }
    .thumb-strip::-webkit-scrollbar { height: 8px; }
    .thumb-strip::-webkit-scrollbar-thumb {
      background: rgba(255,255,255,0.14);
      border-radius: 999px;
    }

    .thumb {
      flex: 0 0 142px;
      display: grid;
      gap: 8px;
      padding: 8px;
      border-radius: 16px;
      background: rgba(255,255,255,0.03);
      border: 1px solid rgba(255,255,255,0.06);
      cursor: pointer;
      transition: transform 180ms ease, background 180ms ease, border-color 180ms ease;
    }
    .thumb:hover { transform: translateY(-2px); }
    .thumb.active {
      background: rgba(255,255,255,0.08);
      border-color: rgba(255,255,255,0.16);
      box-shadow: 0 10px 25px rgba(0,0,0,0.22);
    }

    .thumb-media {
      aspect-ratio: 1.6 / 1;
      border-radius: 12px;
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.06);
    }

    .thumb-meta {
      display: grid;
      gap: 3px;
      min-width: 0;
    }
    .thumb-title {
      font-size: 11px;
      line-height: 1.35;
      color: var(--white);
      font-family: "Bebas Neue", sans-serif;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .spread-count {
      color: var(--muted);
      line-height: 1.6;
    }

    .hidden { display: none !important; }

    .embed-note {
      position: absolute;
      right: 18px;
      bottom: 18px;
      z-index: 8;
      background: rgba(0,0,0,0.42);
      color: rgba(240,235,226,0.72);
      border: 1px solid rgba(255,255,255,0.08);
      padding: 10px 12px;
      border-radius: 14px;
      font-size: 10px;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      backdrop-filter: blur(12px);
    }

    @media (max-width: 1100px) {
      .viewer-shell {
        grid-template-columns: 60px minmax(0,1fr) 60px;
        grid-template-rows: 72px minmax(0,1fr) 120px;
      }
      .thumb-dock {
        grid-template-columns: 1fr;
      }
      .thumb-dock .left-meta,
      .thumb-dock .right-meta {
        display: none;
      }
      .magazine { max-height: 70vh; }
    }

    @media (max-width: 820px) {
      body { overflow: auto; }
      .viewer-shell {
        height: auto;
        min-height: 100%;
        grid-template-columns: 1fr;
        grid-template-rows: auto auto auto auto;
      }
      .topbar {
        position: sticky;
        top: 0;
      }
      .side-rail {
        display: none;
      }
      .stage-wrap {
        padding: 18px 16px;
      }
      .magazine {
        height: auto;
        max-height: none;
        min-height: 0;
      }
      .spread {
        position: relative;
        grid-template-columns: 1fr;
        min-height: 980px;
        border-radius: 24px;
      }
      .spread::before { display: none; }
      .page { min-height: 490px; }
      .thumb-dock { padding-bottom: 24px; }
      .embed-note { position: static; margin-top: 14px; }
    }
  </style>
</head>
<body>
  <div class="viewer-shell">
    <header class="topbar">
      <div class="brand">
        <small>Portfolio Embed / Editorial Viewer</small>
        <strong>RANAAN × CCC — Future Archives</strong>
      </div>
      <div class="topbar-actions">
        <button class="chip" id="openTocBtn" type="button">Contents</button>
        <button class="toggle" id="fitToggle" type="button">Fullscreen Spread</button>
        <div class="spread-count" id="spreadCount">01 / 06</div>
      </div>
    </header>

    <aside class="side-rail">
      <button class="nav-btn" id="prevBtn" type="button" aria-label="Previous spread">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M15 18l-6-6 6-6"/></svg>
      </button>
    </aside>

    <main class="stage-wrap">
      <div class="magazine">
        <div class="spread-stack" id="spreadStack"></div>
      </div>
      <div class="embed-note">Replace image URLs + text blocks in the data array</div>
    </main>

    <aside class="side-rail">
      <button class="nav-btn" id="nextBtn" type="button" aria-label="Next spread">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M9 6l6 6-6 6"/></svg>
      </button>
    </aside>

    <footer class="thumb-dock" id="thumbDock">
      <div class="left-meta">
        <div class="thumb-label">Issue Build</div>
        <div class="notes">Editorial viewer with page-turn motion, thumbnail dock, keyboard nav, and embed-ready single file.</div>
      </div>
      <div class="thumb-strip" id="thumbStrip"></div>
      <div class="right-meta">
        <div class="thumb-label">Keys</div>
        <div class="notes">← → navigate · T contents · F fit spread</div>
      </div>
    </footer>
  </div>

  <script>
    // Replace these objects with your real campaign spreads and image URLs.
    const editorialData = [
      {
        id: "cover",
        thumbLabel: "Cover",
        left: {
          theme: "dark",
          kicker: "RANAAN × CCC / Editorial Project",
          title: "Future\nArchives",
          deck: "A portfolio-ready magazine object for campaign imagery, multilingual microtext, and brutalist editorial pacing.",
          quote: "Controlled chaos arranged as a printed memory.",
          body: "Use this spread as your project cover. Swap the copy, issue number, project subtitle, and masthead. The layout is built to feel like a printed magazine viewed on-screen rather than a slideshow.",
          meta: [
            ["Issue", "01 / Prototype"],
            ["Format", "Interactive Spread"],
            ["Mood", "Brutalist / Analog / Cinematic"]
          ],
          notes: [
            "Fonts: Bebas Neue / Playfair Display / Space Mono",
            "Palette: void black / bone cream / ash / blood accent"
          ]
        },
        right: {
          media: null,
          mediaLabel: "Drop in cover image",
          mediaTags: ["Cover", "Hero Frame", "4:5 or 16:9"]
        }
      },
      {
        id: "s01",
        thumbLabel: "Spread 01",
        left: {
          media: null,
          mediaLabel: "Hero image — loading dock / pit / exterior",
          mediaTags: ["Shot 01", "Campaign opener", "Multi-ethnic cast"]
        },
        right: {
          kicker: "Spread 01 / Opening Statement",
