            "Swap the thumbnail dock for a side TOC if your portfolio already has navigation."
          ]
        },
        right: {
          media: null,
          mediaLabel: "Credits page art / back cover / logo study",
          mediaTags: ["Back cover", "Credits", "Portfolio link"]
