export default function RanaanCccEditorialViewer() {
  const [current, setCurrent] = useState(0);
  const [isFitMode, setIsFitMode] = useState(false);
  const [direction, setDirection] = useState<1 | -1 | 0>(0);
  const [animating, setAnimating] = useState(false);
  const thumbRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const total = editorialData.length;

  const spreads = useMemo(() => editorialData, []);

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "ArrowRight") goTo(current + 1);
      if (e.key === "ArrowLeft") goTo(current - 1);
      if (e.key.toLowerCase() === "f") setIsFitMode((v) => !v);
      if (e.key.toLowerCase() === "t") {
        thumbRefs.current[current]?.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" });
        thumbRefs.current[current]?.focus();
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [current]);

  useEffect(() => {
    thumbRefs.current[current]?.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" });
  }, [current]);

  const goTo = (index: number) => {
    if (animating) return;
    if (index < 0 || index >= total || index === current) return;

    setAnimating(true);
    setDirection(index > current ? 1 : -1);
    setCurrent(index);

    window.setTimeout(() => {
      setAnimating(false);
      setDirection(0);
    }, 680);
  };

  return (
    <div className="relative h-screen w-full overflow-hidden bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.05),transparent_26%),linear-gradient(180deg,#121212_0%,#090909_55%,#060606_100%)] text-white">
