      <div className="grid h-full grid-cols-[86px_minmax(0,1fr)_86px] grid-rows-[72px_minmax(0,1fr)_96px] max-[1100px]:grid-cols-[60px_minmax(0,1fr)_60px] max-[1100px]:grid-rows-[72px_minmax(0,1fr)_120px] max-[820px]:block max-[820px]:min-h-screen max-[820px]:h-auto">
        <header className="col-span-full flex items-center justify-between gap-4 border-b border-white/10 bg-[linear-gradient(180deg,rgba(255,255,255,0.03),rgba(255,255,255,0.01))] px-6 py-[18px] backdrop-blur-[14px] max-[820px]:sticky max-[820px]:top-0 max-[820px]:z-20">
          <div className="min-w-0">
            <div className="text-[10px] uppercase tracking-[0.22em] text-[#8e857b]">Portfolio Embed / Editorial Viewer</div>
            <div className="truncate font-['Bebas_Neue'] text-[30px] uppercase leading-[0.92] tracking-[0.06em]">RANAAN × CCC — Future Archives</div>
          </div>

          <div className="flex flex-wrap items-center justify-end gap-2">
            <button
              type="button"
              onClick={() => thumbRefs.current[current]?.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" })}
              className="h-9 rounded-full border border-white/10 bg-white/5 px-4 text-[10px] uppercase tracking-[0.22em] transition hover:-translate-y-[1px] hover:bg-white/10"
            >
              Contents
            </button>
            <button
              type="button"
              onClick={() => setIsFitMode((v) => !v)}
              className="h-9 rounded-full border border-white/10 bg-white/5 px-4 text-[10px] uppercase tracking-[0.22em] transition hover:-translate-y-[1px] hover:bg-white/10"
            >
              {isFitMode ? "Standard View" : "Fullscreen Spread"}
            </button>
            <div className="text-[10px] uppercase tracking-[0.22em] text-[#8e857b]">
              {String(current + 1).padStart(2, "0")} / {String(total).padStart(2, "0")}
            </div>
          </div>
        </header>

        <aside className="flex items-center justify-center p-3 max-[820px]:hidden">
          <button
            type="button"
            onClick={() => goTo(current - 1)}
            disabled={current === 0}
            className="flex h-[54px] w-[54px] items-center justify-center rounded-full border border-white/10 bg-white/5 shadow-[0_18px_40px_rgba(0,0,0,0.28)] transition hover:-translate-y-[1px] hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-35"
            aria-label="Previous spread"
          >
            <svg viewBox="0 0 24 24" className="h-[18px] w-[18px]" fill="none" stroke="currentColor" strokeWidth="1.8">
              <path d="M15 18l-6-6 6-6" />
            </svg>
          </button>
        </aside>

        <main className="relative grid min-h-0 min-w-0 place-items-center overflow-hidden px-[clamp(12px,2vw,22px)] pb-3 pt-[22px] max-[820px]:px-4 max-[820px]:pt-[18px]">
          <div className="pointer-events-none absolute h-[min(70vh,760px)] w-[min(78vw,1080px)] translate-y-[4%] rounded-full bg-[radial-gradient(circle,rgba(255,255,255,0.07)_0%,transparent_70%)] blur-[20px]" />

          <div className={classNames("relative w-full max-w-[1440px] min-w-0", isFitMode ? "h-[82vh] max-[820px]:h-auto" : "h-[min(76vh,calc((100vw-280px)*0.58))] min-h-[420px] max-[820px]:h-auto max-[820px]:min-h-0")}>
            <div className="relative h-full w-full [transform-style:preserve-3d]">
              {spreads.map((spread, index) => {
                const isActive = index === current;
