                    key={spread.id}
                    className={cx(
                      "absolute inset-0 grid grid-cols-2 overflow-hidden rounded-[22px] bg-[linear-gradient(180deg,#ede5d8,#e7dfd1)] text-[#101010] shadow-[0_30px_80px_rgba(0,0,0,0.5)] transition-[transform,opacity] duration-[620ms] [transform-origin:center_center] max-[820px]:relative max-[820px]:grid-cols-1 max-[820px]:min-h-[980px] max-[820px]:rounded-[24px]",
                      isActive && "z-[4] translate-x-0 rotate-y-0 scale-100 opacity-100 pointer-events-auto",
                      isBefore && "z-[2] -translate-x-[70px] rotate-y-[14deg] scale-[0.98] opacity-0 pointer-events-none",
                      isAfter && "z-[2] translate-x-[70px] -rotate-y-[14deg] scale-[0.98] opacity-0 pointer-events-none",
                      !isActive && !isBefore && !isAfter && "translate-x-[60px] -rotate-y-[10deg] scale-[0.985] opacity-0 pointer-events-none",
                      animating && isActive && "will-change-transform"
                    )}
                  >
                    <div className="pointer-events-none absolute inset-y-0 left-1/2 z-[3] hidden w-[22px] -translate-x-1/2 bg-[linear-gradient(90deg,rgba(0,0,0,0.15),rgba(255,255,255,0.08),rgba(0,0,0,0.15))] opacity-65 md:block" />
                    <div className="pointer-events-none absolute inset-y-0 right-0 z-[3] w-[22px] bg-[linear-gradient(90deg,transparent,rgba(0,0,0,0.08))] opacity-45" />

                    <MagazinePage side={spread.left} pageNumber={index * 2 + 1} />
                    <MagazinePage side={spread.right} pageNumber={index * 2 + 2} />
                  </article>
                );
              })}
            </div>
          </div>

          <div className="absolute bottom-[18px] right-[18px] z-[8] rounded-[14px] border border-white/10 bg-black/40 px-3 py-2 text-[10px] uppercase tracking-[0.18em] text-[#f0ebe2]/70 backdrop-blur-[12px] max-[820px]:static max-[820px]:mt-[14px]">
            JSON-driven issue viewer / swap image URLs in the issue file
          </div>
        </main>

        <aside className="flex items-center justify-center p-3 max-[820px]:hidden">
          <button
            type="button"
            onClick={() => goTo(current + 1)}
            disabled={current === total - 1}
            className="flex h-[54px] w-[54px] items-center justify-center rounded-full border border-white/10 bg-white/5 shadow-[0_18px_40px_rgba(0,0,0,0.28)] transition hover:-translate-y-[1px] hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-35"
            aria-label="Next spread"
          >
            <svg viewBox="0 0 24 24" className="h-[18px] w-[18px]" fill="none" stroke="currentColor" strokeWidth="1.8">
              <path d="M9 6l6 6-6 6" />
            </svg>
          </button>
        </aside>

        {!isFitMode ? (
          <footer className="col-span-full grid grid-cols-[180px_minmax(0,1fr)_150px] items-center gap-4 border-t border-white/10 bg-[linear-gradient(180deg,rgba(255,255,255,0.01),rgba(255,255,255,0.03))] px-5 pb-[18px] pt-3 max-[1100px]:grid-cols-1 max-[820px]:pb-6">
            <div className="min-w-0 text-[#8e857b] max-[1100px]:hidden">
              <div className="text-[10px] uppercase tracking-[0.22em]">Issue Build</div>
              <div className="mt-1 grid gap-1 text-[10px] uppercase tracking-[0.18em] text-[#8e857b]">
                <div>Editorial viewer with page-turn motion, thumbnail dock, keyboard nav, and shared JSON issue data.</div>
              </div>
            </div>

            <div className="flex gap-3 overflow-x-auto pb-1 [scrollbar-color:rgba(255,255,255,0.18)_transparent] [scrollbar-width:thin]">
              {spreads.map((spread, index) => {
                const imgSrc = spread.right.media || spread.left.media;
                return (
                  <button
                    key={spread.id}
                    ref={(el) => {
                      thumbRefs.current[index] = el;
                    }}
                    type="button"
                    onClick={() => goTo(index)}
                    className={cx(
                      "grid w-[142px] flex-none gap-2 rounded-[16px] border px-2 py-2 text-left transition",
                      index === current
                        ? "border-white/20 bg-white/10 shadow-[0_10px_25px_rgba(0,0,0,0.22)]"
                        : "border-white/10 bg-white/5 hover:-translate-y-[2px] hover:bg-white/8"
                    )}
                  >
                    <div
                      className={cx(
                        "relative aspect-[1.6/1] overflow-hidden rounded-[12px] border border-white/10 shadow-[inset_0_0_0_1px_rgba(255,255,255,0.06)]",
                        imgSrc
                          ? "bg-neutral-900"
                          : "bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.12),transparent_25%),linear-gradient(135deg,#191919,#0e0e0e_55%,#1a0a0a)]"
                      )}
                    >
                      {imgSrc ? (
                        <img src={imgSrc} alt={spread.thumbLabel} className="block h-full w-full object-cover saturate-90 contrast-[1.02]" />
                      ) : (
                        <>
                          <div className="pointer-events-none absolute inset-0 opacity-45 [background-image:linear-gradient(rgba(255,255,255,0.04)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.04)_1px,transparent_1px)] [background-size:28px_28px]" />
                          <div className="absolute bottom-3 left-3 text-[10px] uppercase tracking-[0.22em] text-[#f0ebe2]/70">{spread.thumbLabel}</div>
                        </>
                      )}
                    </div>

                    <div className="grid gap-[3px] min-w-0">
                      <div className="truncate font-['Bebas_Neue'] text-[11px] uppercase tracking-[0.06em] text-white">{spread.thumbLabel}</div>
                      <div className="text-[10px] uppercase tracking-[0.22em] text-[#8e857b]">
                        {String(index + 1).padStart(2, "0")} / {String(total).padStart(2, "0")}
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="min-w-0 text-[#8e857b] max-[1100px]:hidden">
              <div className="text-[10px] uppercase tracking-[0.22em]">Keys</div>
              <div className="mt-1 grid gap-1 text-[10px] uppercase tracking-[0.18em]">
                <div>← → navigate · T contents · F fit spread</div>
              </div>
            </div>
          </footer>
        ) : null}
      </div>
    </div>
  );
}


