    .thumb-strip::-webkit-scrollbar { height: 8px; }
    .thumb-strip::-webkit-scrollbar-thumb {
      background: rgba(255,255,255,0.14);
      border-radius: 999px;
    }

    .thumb {
      flex: 0 0 142px;
      display: grid;
      gap: 8px;
      padding: 8px;
      border-radius: 16px;
      background: rgba(255,255,255,0.03);
      border: 1px solid rgba(255,255,255,0.06);
      cursor: pointer;
      transition: transform 180ms ease, background 180ms ease, border-color 180ms ease;
    }

    .thumb:hover { transform: translateY(-2px); }
    .thumb.active {
      background: rgba(255,255,255,0.08);
      border-color: rgba(255,255,255,0.16);
      box-shadow: 0 10px 25px rgba(0,0,0,0.22);
    }

    .thumb-media {
      aspect-ratio: 1.6 / 1;
      border-radius: 12px;
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.06);
    }

    .thumb-meta { display: grid; gap: 3px; min-width: 0; }
    .thumb-title {
      font-family: "Bebas Neue", sans-serif;
      letter-spacing: 0.06em;
      color: var(--white);
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .spread-count,
    .thumb-label,
    .notes { color: var(--muted); }

    .hidden { display: none !important; }

    .embed-note {
      position: absolute;
      right: 18px;
      bottom: 18px;
      z-index: 8;
      background: rgba(0,0,0,0.42);
      color: rgba(240,235,226,0.72);
      border: 1px solid rgba(255,255,255,0.08);
      padding: 10px 12px;
      border-radius: 14px;
      font-size: 10px;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      backdrop-filter: blur(12px);
    }

    @media (max-width: 1100px) {
      .viewer-shell {
        grid-template-columns: 60px minmax(0,1fr) 60px;
        grid-template-rows: 72px minmax(0,1fr) 120px;
      }
      .thumb-dock { grid-template-columns: 1fr; }
      .thumb-dock .left-meta,
      .thumb-dock .right-meta { display: none; }
    }

    @media (max-width: 820px) {
      body { overflow: auto; }
      .viewer-shell {
        display: block;
        min-height: 100%;
        height: auto;
      }
      .topbar { position: sticky; top: 0; }
      .side-rail { display: none; }
      .stage-wrap { padding: 18px 16px; }
      .magazine { height: auto; min-height: 0; }
      .spread {
        position: relative;
        grid-template-columns: 1fr;
        min-height: 980px;
        border-radius: 24px;
      }
      .spread::before { display: none; }
      .page { min-height: 490px; }
      .thumb-dock { padding-bottom: 24px; }
      .embed-note { position: static; margin-top: 14px; }
    }
  </style>
</head>
