        <small>Portfolio Embed / Editorial Viewer</small>
        <strong id="projectTitle">RANAAN × CCC — Future Archives</strong>
      </div>
      <div class="topbar-actions">
        <button class="chip" id="openTocBtn" type="button">Contents</button>
        <button class="toggle" id="fitToggle" type="button">Fullscreen Spread</button>
        <div class="spread-count" id="spreadCount">01 / 10</div>
      </div>
    </header>

    <aside class="side-rail">
      <button class="nav-btn" id="prevBtn" type="button" aria-label="Previous spread">
        <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M15 18l-6-6 6-6"/></svg>
      </button>
    </aside>

    <main class="stage-wrap">
      <div class="magazine">
        <div class="spread-stack" id="spreadStack"></div>
      </div>
      <div class="embed-note">JSON-driven issue viewer / swap image URLs in the issue file</div>
    </main>

    <aside class="side-rail">
      <button class="nav-btn" id="nextBtn" type="button" aria-label="Next spread">
        <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M9 6l6 6-6 6"/></svg>
      </button>
    </aside>

    <footer class="thumb-dock" id="thumbDock">
      <div class="left-meta">
        <div class="thumb-label">Issue Build</div>
        <div class="notes">Editorial viewer with page-turn motion, thumbnail dock, keyboard nav, and shared JSON issue data.</div>
      </div>
      <div class="thumb-strip" id="thumbStrip"></div>
      <div class="right-meta">
        <div class="thumb-label">Keys</div>
        <div class="notes">← → navigate · T contents · F fit spread</div>
      </div>
    </footer>
  </div>

  <script>
    let issue = null;
    let editorialData = [];

    const spreadStack = document.getElementById('spreadStack');
    const thumbStrip = document.getElementById('thumbStrip');
    const spreadCount = document.getElementById('spreadCount');
    const prevBtn = document.getElementById('prevBtn');
    const nextBtn = document.getElementById('nextBtn');
    const fitToggle = document.getElementById('fitToggle');
    const openTocBtn = document.getElementById('openTocBtn');
    const projectTitle = document.getElementById('projectTitle');

    let current = 0;
    let animating = false;

    function createMediaPanel(side) {
      const hasImage = !!side.media;
      const panel = document.createElement('div');
      panel.className = `img-panel ${hasImage ? '' : 'placeholder'}`.trim();
      if (!hasImage) panel.dataset.label = side.mediaLabel || 'Add image';

      const micro = document.createElement('div');
      micro.className = 'micrographics';
      panel.appendChild(micro);

      if (hasImage) {
        const img = document.createElement('img');
        img.src = side.media;
        img.alt = side.mediaAlt || side.mediaLabel || 'Editorial image';
        panel.appendChild(img);
      }

      (side.mediaTags || []).slice(0, 3).forEach((tag, idx) => {
        const pill = document.createElement('div');
        pill.className = 'micro-tag';
        pill.textContent = tag;
        const presets = [
          { top: '16px', right: '16px' },
          { bottom: '18px', left: '18px' },
          { top: '50%', right: '18px', transform: 'translateY(-50%)' }
        ][idx];
        Object.assign(pill.style, presets);
        panel.appendChild(pill);
      });

      return panel;
    }

    function createTextPage(side, pageNumber) {
      const page = document.createElement('section');
      page.className = `page ${side.theme === 'dark' ? 'dark' : ''}`;

      const head = document.createElement('div');
      head.className = 'page-head';
      head.innerHTML = `
        <div class="kicker">${side.kicker || ''}</div>
        <div class="page-no">${String(pageNumber).padStart(2, '0')}</div>
      `;
      page.appendChild(head);

      const block = document.createElement('div');

      if (side.title) {
        const title = document.createElement('h2');
        title.className = side.title.length > 18 ? 'spread-title' : 'hero-title';
        title.innerHTML = side.title.replace(/\n/g, '<br>');
        block.appendChild(title);
      }

      if (side.deck) {
        const deck = document.createElement('p');
        deck.className = 'deck-line';
        deck.textContent = side.deck;
        block.appendChild(deck);
      }

      if (side.quote) {
        const quote = document.createElement('blockquote');
        quote.className = 'pull-quote';
        quote.textContent = side.quote;
        block.appendChild(quote);
      }

      if (side.body) {
        const body = document.createElement('div');
        body.className = 'body-copy';
        body.textContent = side.body;
        block.appendChild(body);
      }

      if (side.meta?.length) {
        const meta = document.createElement('div');
        meta.className = 'micro-list';
        side.meta.forEach(([k, v]) => {
          const row = document.createElement('div');
          row.className = 'micro';
          row.innerHTML = `<span>${k}</span><span>${v}</span>`;
          meta.appendChild(row);
        });
        block.appendChild(meta);
      }

      if (side.notes?.length) {
        const notes = document.createElement('div');
        notes.className = 'notes';
        side.notes.forEach((item) => {
          const line = document.createElement('div');
          line.textContent = item;
          notes.appendChild(line);
        });
        block.appendChild(notes);
      }

      page.appendChild(block);

      const foot = document.createElement('div');
      foot.className = 'page-foot';
      foot.innerHTML = `<div class="caption">${side.footer || 'Editorial page'}</div>`;
      page.appendChild(foot);
      return page;
    }

    function createMediaPage(side, pageNumber) {
      const page = document.createElement('section');
      page.className = `page ${side.theme === 'dark' ? 'dark' : ''}`;

      const head = document.createElement('div');
      head.className = 'page-head';
      head.innerHTML = `
        <div class="kicker">${side.kicker || ''}</div>
        <div class="page-no">${String(pageNumber).padStart(2, '0')}</div>
      `;
      page.appendChild(head);
      page.appendChild(createMediaPanel(side));

      const foot = document.createElement('div');
      foot.className = 'page-foot';
      foot.innerHTML = `<div class="caption">${side.footer || side.mediaLabel || 'Campaign image'}</div>`;
      page.appendChild(foot);
      return page;
    }

    function buildSpread(item, index) {
      const spread = document.createElement('article');
      spread.className = 'spread';
      spread.dataset.index = index;

      const leftPage = (item.left.media !== undefined || item.left.mediaLabel)
        ? createMediaPage(item.left, index * 2 + 1)
        : createTextPage(item.left, index * 2 + 1);

      const rightPage = (item.right.media !== undefined || item.right.mediaLabel)
        ? createMediaPage(item.right, index * 2 + 2)
        : createTextPage(item.right, index * 2 + 2);

      spread.appendChild(leftPage);
      spread.appendChild(rightPage);
      return spread;
    }

    function buildThumb(item, index) {
      const thumb = document.createElement('button');
      thumb.className = 'thumb';
      thumb.type = 'button';
      thumb.dataset.index = index;
      thumb.setAttribute('aria-label', `Open ${item.thumbLabel}`);

      const media = document.createElement('div');
      const imgSrc = item.right?.media || item.left?.media;
      media.className = `thumb-media ${imgSrc ? '' : 'placeholder'}`.trim();
      if (!imgSrc) media.dataset.label = item.thumbLabel;

      if (imgSrc) {
        const img = document.createElement('img');
        img.src = imgSrc;
        img.alt = item.thumbLabel;
        media.appendChild(img);
      }

      const meta = document.createElement('div');
      meta.className = 'thumb-meta';
      meta.innerHTML = `
        <div class="thumb-title">${item.thumbLabel}</div>
        <div class="thumb-label">${String(index + 1).padStart(2, '0')} / ${String(editorialData.length).padStart(2, '0')}</div>
      `;

      thumb.appendChild(media);
      thumb.appendChild(meta);
      thumb.addEventListener('click', () => goTo(index));
      return thumb;
    }

    function render() {
      spreadStack.innerHTML = '';
      thumbStrip.innerHTML = '';

      editorialData.forEach((item, index) => {
        spreadStack.appendChild(buildSpread(item, index));
        thumbStrip.appendChild(buildThumb(item, index));
      });

      updateState(false);
    }

    function updateState(scrollThumb = true) {
      const spreads = [...spreadStack.querySelectorAll('.spread')];
      const thumbs = [...thumbStrip.querySelectorAll('.thumb')];

      spreads.forEach((spread, idx) => {
        spread.classList.remove('active', 'before', 'after');
        if (idx < current) spread.classList.add('before');
        else if (idx > current) spread.classList.add('after');
        else spread.classList.add('active');
      });

      thumbs.forEach((thumb, idx) => {
        thumb.classList.toggle('active', idx === current);
      });

      spreadCount.textContent = `${String(current + 1).padStart(2, '0')} / ${String(editorialData.length).padStart(2, '0')}`;
      prevBtn.disabled = current === 0;
      nextBtn.disabled = current === editorialData.length - 1;

      if (scrollThumb) {
        thumbs[current]?.scrollIntoView({ inline: 'center', behavior: 'smooth', block: 'nearest' });
      }
    }

    function goTo(index) {
      if (animating || index === current || index < 0 || index >= editorialData.length) return;
      animating = true;
      current = index;
      updateState(true);
      window.setTimeout(() => { animating = false; }, 620);
    }

    function next() { goTo(Math.min(editorialData.length - 1, current + 1)); }
    function prev() { goTo(Math.max(0, current - 1)); }

    prevBtn.addEventListener('click', prev);
    nextBtn.addEventListener('click', next);

    fitToggle.addEventListener('click', () => {
      document.body.classList.toggle('fit-mode');
      fitToggle.textContent = document.body.classList.contains('fit-mode') ? 'Standard View' : 'Fullscreen Spread';
      document.querySelector('.thumb-dock')?.classList.toggle('hidden');
    });

    openTocBtn.addEventListener('click', () => {
      document.getElementById('thumbDock').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      const activeThumb = thumbStrip.querySelector('.thumb.active');
      activeThumb?.focus();
    });

    window.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowRight') next();
      if (e.key === 'ArrowLeft') prev();
      if (e.key.toLowerCase() === 'f') fitToggle.click();
      if (e.key.toLowerCase() === 't') openTocBtn.click();
    });

    let startX = 0;
    let endX = 0;
    document.querySelector('.stage-wrap').addEventListener('touchstart', (e) => {
      startX = e.changedTouches[0].clientX;
    }, { passive: true });

    document.querySelector('.stage-wrap').addEventListener('touchend', (e) => {
      endX = e.changedTouches[0].clientX;
      const delta = endX - startX;
      if (Math.abs(delta) < 40) return;
      if (delta < 0) next();
      if (delta > 0) prev();
    }, { passive: true });

    fetch('./ranaan-ccc-editorial-issue-final.json')
      .then((res) => res.json())
      .then((data) => {
        issue = data;
        editorialData = data.spreads || [];
        if (data.project?.title) {
          projectTitle.textContent = data.project.title;
          document.title = data.project.title;
        }
        render();
      })
      .catch((err) => {
        console.error('Failed to load issue JSON:', err);
      });
  </script>
</body>
</html>


